async function mGet(url,o={}){const r=await fetch(url,{method:o.method||'GET',headers:{'User-Agent':MUA,'Accept-Language':'en-US,en;q=0.9',...(o.headers||{})},body:o.body,signal:AbortSignal.timeout(o.timeout||30000),redirect:'follow'});
 if(!r.ok)throw new Error('HTTP '+r.status+' · '+url.replace(/\?.*/,''));const buf=Buffer.from(await r.arrayBuffer());return {buf,text:()=>buf.toString('utf8'),cookie:(r.headers.getSetCookie?r.headers.getSetCookie():[]).map(c=>c.split(';')[0]).join('; ')}}
const mNum=s=>{const v=parseFloat(String(s).replace(/[$,\s]/g,''));return Number.isFinite(v)?v:null};
const mDay=(d=new Date())=>new Date(d).toISOString().slice(0,10);
const mStrip=s=>String(s).replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/\s+/g,' ').trim();
/* minimal .xlsx reader (zip + sharedStrings + one sheet) */
function xlsxSheet(buf,want){const eo=buf.lastIndexOf(Buffer.from([0x50,0x4b,0x05,0x06]));if(eo<0)throw new Error('xlsx نامعتبر');const n=buf.readUInt16LE(eo+10);let p=buf.readUInt32LE(eo+16);const F={};
 for(let i=0;i<n;i++){const m=buf.readUInt16LE(p+10),cs=buf.readUInt32LE(p+20),nl=buf.readUInt16LE(p+28),el=buf.readUInt16LE(p+30),cl=buf.readUInt16LE(p+32),lo=buf.readUInt32LE(p+42);const name=buf.toString('utf8',p+46,p+46+nl);F[name]={m,cs,lo};p+=46+nl+el+cl}
 const rd=nm=>{const f=F[nm];if(!f)return null;const l=f.lo,s=l+30+buf.readUInt16LE(l+26)+buf.readUInt16LE(l+28);const d=buf.subarray(s,s+f.cs);return (f.m===8?zlib.inflateRawSync(d):d).toString('utf8')};
 const wb=rd('xl/workbook.xml')||'',rels=rd('xl/_rels/workbook.xml.rels')||'';const sh=[...wb.matchAll(/<sheet [^>]*name="([^"]+)"[^>]*r:id="([^"]+)"/g)].find(x=>want.test(x[1]));if(!sh)throw new Error('برگهٔ موردنظر یافت نشد');
 const tg=(rels.match(new RegExp('Id="'+sh[2]+'"[^>]*Target="([^"]+)"'))||rels.match(new RegExp('Target="([^"]+)"[^>]*Id="'+sh[2]+'"'))||[])[1];const ss=[...(rd('xl/sharedStrings.xml')||'').matchAll(/<si>([\s\S]*?)<\/si>/g)].map(x=>mStrip(x[1].replace(/<rPh[\s\S]*?<\/rPh>/g,'')));
 const xml=rd('xl/'+String(tg).replace(/^\/?xl\//,''))||'';const rows=[];for(const r of xml.matchAll(/<row [^>]*r="(\d+)"[^>]*>([\s\S]*?)<\/row>/g)){const o={};for(const c of r[2].matchAll(/<c r="([A-Z]+)\d+"([^>]*?)(?:\/>|>([\s\S]*?)<\/c>)/g)){const v=(c[3]||'').match(/<v>([^<]*)<\/v>/);if(!v)continue;o[c[1]]=/t="s"/.test(c[2])?ss[+v[1]]:/t="str"|t="inlineStr"/.test(c[2])?v[1]:+v[1]}rows[+r[1]]=o}return rows}
const colN=s=>[...s].reduce((a,c)=>a*26+c.charCodeAt(0)-64,0),colL=n=>{let s='';while(n>0){const m=(n-1)%26;s=String.fromCharCode(65+m)+s;n=Math.floor((n-1)/26)}return s};
/* BIFF8 (.xls) numeric-cell scan — used for NY Fed GSCPI */
function xlsNums(b){const rk=v=>{let x;if(v&2)x=v>>2;else{const t=Buffer.alloc(8);t.writeUInt32LE((v&0xfffffffc)>>>0,4);x=t.readDoubleLE(0)}return v&1?x/100:x};const C={};
 for(let i=0;i+14<b.length;i++){const t=b.readUInt16LE(i),l=b.readUInt16LE(i+2);if(t===0x0203&&l===14){const r=b.readUInt16LE(i+4),c=b.readUInt16LE(i+6);(C[r]=C[r]||{})[c]=b.readDoubleLE(i+10)}else if(t===0x027E&&l===10){const r=b.readUInt16LE(i+4),c=b.readUInt16LE(i+6);(C[r]=C[r]||{})[c]=rk(b.readUInt32LE(i+10))}}return C}
