function mktSave(src,out){const meta=out.meta||{};for(const [id,m] of Object.entries(meta))run('INSERT INTO mkt_meta(id,json) VALUES(?,?) ON CONFLICT(id) DO UPDATE SET json=excluded.json',id,JSON.stringify({...m,src}));let n=0,bad=0;
 for(const p of out.points){if(!p.id||!/^\d{4}-\d{2}-\d{2}$/.test(p.date||'')||!Number.isFinite(p.value))continue;const k=(meta[p.id]||{}).kind;const rg=MRANGE[k];let flag=p.flag||'';if(rg&&(p.value<rg[0]||p.value>rg[1])){bad++;continue}
  const prev=q1('SELECT value FROM mkt WHERE id=? AND date<? ORDER BY date DESC LIMIT 1',p.id,p.date);const j=MJUMP[k];if(prev&&j&&prev.value&&(k==='macro'?Math.abs(p.value-prev.value)>j:Math.abs(p.value/prev.value-1)>j))flag=(flag?flag+',':'')+'jump';
  run('INSERT INTO mkt(id,date,value,src,ts,flag) VALUES(?,?,?,?,?,?) ON CONFLICT(id,date) DO UPDATE SET value=excluded.value,ts=excluded.ts,flag=excluded.flag',p.id,p.date,p.value,src,Date.now(),flag);n++}return {n,bad}}
async function mktRun(only,by){if(MKST.busy)return {busy:true};MKST.busy=true;const res={};try{const ids=Object.keys(MSRC).filter(k=>(!only||only.includes(k))&&CFG.market.sources[k]!==false);
 for(const k of ids){const t0=Date.now();try{const out=await MSRC[k].run();const r=mktSave(k,out);let file='';if(out.raw&&CFG.market.keepRaw!==false){const dir=path.join(CFG.dataDir,'market',mDay());fs.mkdirSync(dir,{recursive:true});file=path.join(dir,k+'-'+Date.now()+'.gz');fs.writeFileSync(file,zlib.gzipSync(out.raw))}
   run('INSERT INTO mkt_run(src,ts,ok,n,ms,bytes,sha,err,file) VALUES(?,?,?,?,?,?,?,?,?)',k,Date.now(),1,r.n,Date.now()-t0,out.raw?out.raw.length:0,out.raw?sha(out.raw):'',r.bad?r.bad+' نقطهٔ خارج از بازهٔ مجاز رد شد':'',file?path.relative(CFG.dataDir,file):'');res[k]={ok:true,n:r.n}}
  catch(e){run('INSERT INTO mkt_run(src,ts,ok,n,ms,bytes,sha,err,file) VALUES(?,?,?,?,?,?,?,?,?)',k,Date.now(),0,0,Date.now()-t0,0,'',String(e.message||e).slice(0,300),'');res[k]={ok:false,err:e.message}}}
 if(by)audit(by,'','market.refresh','market',(only||['all']).join(','),res);try{mktAlerts()}catch(e){console.error('market alerts',e.message)}
 const old=Date.now()-(CFG.market.rawDays||60)*864e5;const md=path.join(CFG.dataDir,'market');if(fs.existsSync(md))for(const d of fs.readdirSync(md))if(/^\d{4}-\d{2}-\d{2}$/.test(d)&&Date.parse(d)<old)fs.rmSync(path.join(md,d),{recursive:true,force:true});return res}finally{MKST.busy=false}}
function mktSeries(id,n=120){return q('SELECT date,value,flag FROM mkt WHERE id=? ORDER BY date DESC LIMIT ?',id,n).reverse()}
function mktAll(n=60){const meta=Object.fromEntries(q('SELECT * FROM mkt_meta').map(r=>[r.id,JSON.parse(r.json)]));const ids=q('SELECT DISTINCT id FROM mkt').map(r=>r.id);
 return ids.map(id=>{const m=meta[id]||{};const h=mktSeries(id,n);return {id,...m,unofficial:m.flag==='unofficial',pts:h.map(x=>[x.date,x.value]),flags:Object.fromEntries(h.filter(x=>x.flag).map(x=>[x.date,x.flag]))}})}
function mktStatus(){return Object.entries(MSRC).map(([k,s])=>{const L=q1('SELECT * FROM mkt_run WHERE src=? ORDER BY id DESC LIMIT 1',k),O=q1('SELECT ts FROM mkt_run WHERE src=? AND ok=1 ORDER BY id DESC LIMIT 1',k);
 return {id:k,name:s.name,url:s.url,licence:s.lic,unofficial:!!s.unofficial,everyHours:s.hours,enabled:CFG.market.sources[k]!==false,lastRun:L&&L.ts,ok:L?!!L.ok:null,err:L&&!L.ok?L.err:(L&&L.err)||'',lastOk:O&&O.ts,points:L&&L.n,sha:L&&L.sha,file:L&&L.file}})}
function mktLast(id){const r=q1('SELECT date,value FROM mkt WHERE id=? ORDER BY date DESC LIMIT 1',id);return r}
function mktAlerts(){const A=kvGet('ifa-mkt-alr')||[];const today=mDay();for(const a of A){if(!a||a.off||!a.sid)continue;const h=mktSeries(a.sid,2);if(!h.length)continue;const cur=h[h.length-1].value,prv=h.length>1?h[0].value:null;const chg=prv?(cur/prv-1)*100:0;
 const hit=a.op==='gt'?cur>a.v:a.op==='lt'?cur<a.v:a.op==='chg'?Math.abs(chg)>=a.v:false;if(hit){const m=q1('SELECT json FROM mkt_meta WHERE id=?',a.sid);const nm=m?JSON.parse(m.json).name:a.sid;fire('market.alert',{ref:a.sid,series:nm,value:cur,change:chg.toFixed(1)+'%',rule:(a.op==='gt'?'بیشتر از ':a.op==='lt'?'کمتر از ':'تغییر بیش از ')+a.v+(a.op==='chg'?'٪':''),date:h[h.length-1].date},'mkt|'+(a.id||a.sid)+'|'+today)}}}
function mktTick(){if(!CFG.market.enabled)return;const due=Object.entries(MSRC).filter(([k,s])=>{if(CFG.market.sources[k]===false)return false;const L=q1('SELECT ts,ok FROM mkt_run WHERE src=? ORDER BY id DESC LIMIT 1',k);if(!L)return true;const every=(CFG.market.everyHours||s.hours)*3600e3;return Date.now()-L.ts>(L.ok?every:Math.min(every,3*3600e3))}).map(x=>x[0]);if(due.length)mktRun(due,null).catch(e=>console.error('market',e.message))}
setInterval(()=>{try{mktTick()}catch(e){console.error('market',e.message)}},15*60e3);setTimeout(()=>{try{mktTick()}catch(e){}},20000);
route('GET','/api/market',(req)=>{const s=new URL(req.url,'http://x').searchParams;return {ts:Date.now(),enabled:!!CFG.market.enabled,busy:MKST.busy,sources:mktStatus(),series:mktAll(Math.min(400,+s.get('n')||90))}},'');
route('GET','/api/market/series/:id',(req,u,P)=>({id:P.id,pts:mktSeries(P.id,Math.min(2000,+new URL(req.url,'http://x').searchParams.get('n')||500))}),'');
route('POST','/api/market/refresh',async(req,u)=>{const b=await body(req);const only=Array.isArray(b.sources)&&b.sources.length?b.sources.filter(k=>MSRC[k]):null;const r=await mktRun(only,u.username);return {result:r,sources:mktStatus()}},'market.refresh');
route('GET','/api/market/runs',()=>q('SELECT id,src,ts,ok,n,ms,bytes,sha,err,file FROM mkt_run ORDER BY id DESC LIMIT 200'),'audit.read');
route('GET','/api/market/raw/:id',(req,u,P,res)=>{const r=q1('SELECT * FROM mkt_run WHERE id=?',+P.id);if(!r||!r.file)throw E(404,'نسخهٔ خام یافت نشد');const f=path.join(CFG.dataDir,r.file);if(!fs.existsSync(f))throw E(404,'فایل خام پاک شده است');res.writeHead(200,{'Content-Type':'application/octet-stream','Content-Disposition':'attachment; filename="'+r.src+'-'+r.ts+'.raw"','Access-Control-Allow-Origin':CFG.cors});res.end(zlib.gunzipSync(fs.readFileSync(f)));return null},'audit.read');

/* ---------- server ---------- */
const appFile=()=>{if(CFG.appFile&&fs.existsSync(CFG.appFile))return CFG.appFile;for(const f of [path.join(__dirname,'..','dist','index.html'),path.join(__dirname,'public','index.html')])if(fs.existsSync(f))return f;const c=fs.readdirSync(__dirname).filter(f=>/^(asana-logistics|iran-freight-atlas).*\.html$/.test(f)).sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));return c.length?path.join(__dirname,c[c.length-1]):null};
/* app delivery: cached in memory, ETag + gzip/brotli (the single-file app is ~9 MB uncompressed) */
const APPC={f:null,m:0,raw:null,gz:null,br:null,etag:''};
function appBody(f){const st=fs.statSync(f);if(APPC.f!==f||APPC.m!==st.mtimeMs){const raw=fs.readFileSync(f);APPC.f=f;APPC.m=st.mtimeMs;APPC.raw=raw;APPC.gz=null;APPC.br=null;APPC.etag='"'+crypto.createHash('sha256').update(raw).digest('base64url').slice(0,27)+'"'}return APPC}
const zp=(fn,buf,o)=>new Promise((ok,no)=>zlib[fn](buf,o,(e,r)=>e?no(e):ok(r)));
function appEnc(A,enc){if(enc==='br')return A.br||(A.br=zp('brotliCompress',A.raw,{params:{[zlib.constants.BROTLI_PARAM_QUALITY]:9,[zlib.constants.BROTLI_PARAM_SIZE_HINT]:A.raw.length}}));return A.gz||(A.gz=zp('gzip',A.raw,{level:9}))}
async function sendApp(req,res,f){const A=appBody(f);const h={'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-cache','ETag':A.etag,'Vary':'Accept-Encoding','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer','X-Frame-Options':'SAMEORIGIN'};
 if(req.headers['if-none-match']===A.etag){res.writeHead(304,h);return res.end()}const ae=String(req.headers['accept-encoding']||'');const enc=/\bbr\b/.test(ae)?'br':/\bgzip\b/.test(ae)?'gzip':'';let b=A.raw;
 if(enc){try{b=await appEnc(A,enc);h['Content-Encoding']=enc}catch(e){A.br=A.gz=null;b=A.raw}}
 h['Content-Length']=b.length;res.writeHead(200,h);res.end(req.method==='HEAD'?undefined:b)}
function appWarm(){try{const f=appFile();if(f){const A=appBody(f);appEnc(A,'br').catch(()=>{});appEnc(A,'gzip').catch(()=>{})}}catch(e){}}
const srv=http.createServer(async(req,res)=>{try{
 if(req.method==='OPTIONS')return send(res,204,'');const url=new URL(req.url,'http://x');const p=url.pathname;
 const pm=p.match(/^\/p\/([A-Za-z0-9_-]{20,40})(?:\/f\/(\d+))?$/);
 if(pm&&req.method==='GET'){const t=q1('SELECT * FROM portal WHERE token=?',pm[1]);if(!t||t.revoked||t.expires<Date.now())return send(res,404,'<!doctype html><meta charset="utf-8"><body dir="rtl" style="font-family:Tahoma;padding:40px;background:#141414;color:#eee">این پیوند معتبر نیست یا منقضی شده است.</body>');
  if(pm[2]){const f=q1('SELECT * FROM files WHERE id=? AND job=? AND public=1 AND deleted=0',+pm[2],t.job);if(!f)return send(res,404,{error:'سند یافت نشد'});audit('portal','','portal.download','file',f.job+'/'+f.name,null);return streamFile(res,f)}
  run('UPDATE portal SET views=views+1,last_view=? WHERE token=?',Date.now(),t.token);if(t.views===0)fire('portal.view',{ref:t.job});return send(res,200,portalPage(t),{'Cache-Control':'no-store'})}
 if(p==='/favicon.ico'||p==='/logo.png'){res.writeHead(200,{'Content-Type':'image/png','Cache-Control':'max-age=86400'});return res.end(Buffer.from(LOGO,'base64'))}if(!p.startsWith('/api/')){const f=appFile();if(f&&(req.method==='GET'||req.method==='HEAD')&&(p==='/'||p==='/index.html'))return await sendApp(req,res,f);return send(res,404,{error:'یافت نشد'})}
 for(const r of R){if(r.m!==req.method)continue;const m=p.match(r.re);if(!m)continue;let u=null;if(r.perm!==undefined){u=auth(req);need(u,r.perm||null)}
  const out=await r.f(req,u,m.groups||{},res);if(out===null)return;if(out&&out.__code){const c=out.__code;delete out.__code;return send(res,c,out)}return send(res,200,out)}
 send(res,404,{error:'مسیر API یافت نشد'})}catch(e){const c=e.code&&Number.isInteger(e.code)?e.code:500;if(c===500)console.error(e);if(!res.headersSent)send(res,c,{error:e.message||'خطای سرور'})}});
if(require.main===module){srv.listen(CFG.port,CFG.host,()=>{const f=appFile();console.log(`Asana Logistics Team Server ${VERSION} → http://${CFG.host}:${CFG.port}  (data: ${CFG.dataDir})`);appWarm();console.log(f?'app: '+f:'هشدار: فایل برنامه یافت نشد — ابتدا npm run build را اجرا کنید یا appFile را تنظیم کنید')});
 const bye=sig=>{console.log('\n'+sig+' → توقف سرور…');srv.close(()=>{try{db.close()}catch(e){}process.exit(0)});setTimeout(()=>{try{db.close()}catch(e){}process.exit(0)},5000).unref()};process.on('SIGTERM',()=>bye('SIGTERM'));process.on('SIGINT',()=>bye('SIGINT'))}
module.exports={srv,taxId,verhoeff,einvValidate,auditVerify};
